INSERT INTO products (name, slug, description, short_description, category_id, brand_id, sku, price, compare_at_price, images, primary_image, specifications, features, whats_included, compatibility, tags, rating, review_count, stock, is_featured, is_bestseller, is_new_arrival, is_deal, weight) VALUES
('Creality Ender 3 V2 3D Printer', 'creality-ender-3-v2', 'The Creality Ender 3 V2 is an upgraded version of the popular Ender 3 3D printer. Features a 220x220x250mm build volume, silent mainboard, carborundum glass bed, and a meanwell power supply. Perfect for makers and hobbyists.', 'FDM 3D printer with 220x220x250mm build volume', (SELECT id FROM categories WHERE slug='3d-printing'), (SELECT id FROM brands WHERE slug='creality'), '3DP-END3V2', 18999.00, 22999.00, ARRAY['https://images.pexels.com/photos/33977799/pexels-photo-33977799.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/30658383/pexels-photo-30658383.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/20552667/pexels-photo-20552667.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'], 'https://images.pexels.com/photos/33977799/pexels-photo-33977799.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '{"Print Technology":"FDM","Build Volume":"220 x 220 x 250 mm","Layer Resolution":"0.1-0.4 mm","Nozzle Diameter":"0.4 mm","Max Print Speed":"180 mm/s","Filament Diameter":"1.75 mm","Bed Type":"Carborundum Glass","Connectivity":"USB, SD Card","Power Supply":"24V Meanwell","Dimensions":"475 x 470 x 620 mm","Weight":"8 kg"}'::jsonb, ARRAY['220x220x250mm build volume','Silent mainboard','Carborundum glass bed','Meanwell power supply','Resume print function','Open source firmware'], ARRAY['1x Ender 3 V2 3D Printer','1x Glass bed','1x SD card with files','1x Tool kit','1x Power cable'], ARRAY['Cura','PrusaSlicer','Creality Slicer'], ARRAY['3d printer','creality','ender 3','fdm','maker','hobbyist'], 4.7, 189, 25, true, true, false, true, 8000),
('Anycubic Photon Mono SE Resin 3D Printer', 'anycubic-photon-mono-se', 'The Anycubic Photon Mono SE is a high-resolution resin 3D printer with a 6.06-inch monochrome LCD, 4.5 second layer exposure, and 2K resolution. Perfect for detailed miniatures, jewelry, and dental models.', 'Resin 3D printer with 2K monochrome LCD', (SELECT id FROM categories WHERE slug='3d-printing'), (SELECT id FROM brands WHERE slug='anycubic'), '3DP-PHOTON-MONO-SE', 16999.00, 19999.00, ARRAY['https://images.pexels.com/photos/30720501/pexels-photo-30720501.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/33977820/pexels-photo-33977820.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/30658383/pexels-photo-30658383.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'], 'https://images.pexels.com/photos/30720501/pexels-photo-30720501.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '{"Print Technology":"MSLA Resin","Resolution":"2K (1620 x 2560)","Build Volume":"130 x 78 x 160 mm","Layer Height":"0.025-0.1 mm","Light Source":"UV LED","Exposure Time":"1.5-4 seconds","Screen":"6.06 inch monochrome","Connectivity":"USB","Dimensions":"220 x 225 x 415 mm","Weight":"8 kg"}'::jsonb, ARRAY['2K monochrome LCD','Fast 1.5-4s exposure','High-resolution resin printing','130x78x160mm build volume','USB connectivity'], ARRAY['1x Anycubic Photon Mono SE','1x Power Adapter','1x Resin Vat','1x Build Platform','1x Tools Kit','1x Manual'], ARRAY['Anycubic Photon Workshop','Chitubox'], ARRAY['3d printer','resin','anycubic','photon','sls','detailed'], 4.6, 56, 15, true, false, true, true, 8000),
('PLA 3D Printer Filament 1.75mm 1kg - White', 'pla-filament-175-white', 'High-quality PLA 3D printer filament in 1.75mm diameter. 1kg spool in white color. Low warping, easy to print, and biodegradable. Perfect for prototyping and decorative prints.', '1kg PLA filament spool, 1.75mm, white', (SELECT id FROM categories WHERE slug='3d-printing'), (SELECT id FROM brands WHERE slug='creality'), '3DP-PLA-WHT-1KG', 999.00, 1499.00, ARRAY['https://images.pexels.com/photos/20552667/pexels-photo-20552667.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/31137405/pexels-photo-31137405.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/19871842/pexels-photo-19871842.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'], 'https://images.pexels.com/photos/20552667/pexels-photo-20552667.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '{"Material":"PLA","Diameter":"1.75 mm","Diameter Tolerance":"+/- 0.03 mm","Weight":"1 kg","Color":"White","Print Temperature":"190-220 C","Bed Temperature":"50-60 C","Density":"1.25 g/cm3","Tensile Strength":"60 MPa","Biodegradable":"Yes"}'::jsonb, ARRAY['1.75mm diameter','Low warping','Easy to print','Biodegradable','Consistent diameter'], ARRAY['1x 1kg PLA Filament Spool'], ARRAY['Most FDM 3D printers','Creality Ender 3','Prusa MK3','Anycubic'], ARRAY['filament','pla','3d printing','1.75mm','white'], 4.6, 78, 150, false, true, false, false, 1000),
('PLA 3D Printer Filament 1.75mm 1kg - Black', 'pla-filament-175-black', 'High-quality PLA 3D printer filament in 1.75mm diameter. 1kg spool in black color. Low warping, easy to print, and biodegradable. Perfect for functional parts and decorative prints.', '1kg PLA filament spool, 1.75mm, black', (SELECT id FROM categories WHERE slug='3d-printing'), (SELECT id FROM brands WHERE slug='prusa'), '3DP-PLA-BLK-1KG', 1099.00, 1599.00, ARRAY['https://images.pexels.com/photos/19871842/pexels-photo-19871842.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/20552667/pexels-photo-20552667.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'], 'https://images.pexels.com/photos/19871842/pexels-photo-19871842.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '{"Material":"PLA","Diameter":"1.75 mm","Diameter Tolerance":"+/- 0.03 mm","Weight":"1 kg","Color":"Black","Print Temperature":"190-220 C","Bed Temperature":"50-60 C","Density":"1.25 g/cm3","Tensile Strength":"60 MPa","Biodegradable":"Yes"}'::jsonb, ARRAY['1.75mm diameter','Low warping','Easy to print','Biodegradable','Consistent diameter'], ARRAY['1x 1kg PLA Filament Spool'], ARRAY['Most FDM 3D printers','Creality Ender 3','Prusa MK3','Anycubic'], ARRAY['filament','pla','3d printing','1.75mm','black'], 4.7, 67, 120, false, true, false, false, 1000),
('3D Printer Nozzle Set 0.4mm - 10 Pieces', '3d-printer-nozzle-set-10', 'A set of 10 brass 3D printer nozzles in 0.4mm diameter. Compatible with most FDM 3D printers including Creality Ender 3, Prusa, and Anycubic. Easy to install and replace.', '10x 0.4mm brass nozzles for FDM printers', (SELECT id FROM categories WHERE slug='3d-printer-parts'), (SELECT id FROM brands WHERE slug='creality'), '3DP-NOZZLE-04-10', 249.00, 449.00, ARRAY['https://images.pexels.com/photos/31137405/pexels-photo-31137405.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/20688553/pexels-photo-20688553.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'], 'https://images.pexels.com/photos/31137405/pexels-photo-31137405.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '{"Material":"Brass","Nozzle Diameter":"0.4 mm","Thread":"M6","Quantity":"10 pieces","Compatibility":"MK8 style","Temperature":"Up to 260 C","Weight":"4 g each"}'::jsonb, ARRAY['10 brass nozzles','0.4mm diameter','M6 thread','MK8 compatible','Up to 260C'], ARRAY['10x 0.4mm Brass Nozzles','1x Cleaning needle'], ARRAY['Creality Ender 3','Prusa MK3','Anycubic i3','Most MK8-style hotends'], ARRAY['3d printer','nozzle','parts','brass','0.4mm','mk8'], 4.5, 45, 300, false, false, false, false, 40),
('BLTouch Auto Bed Leveling Sensor for 3D Printers', 'bltouch-auto-leveling-sensor', 'The BLTouch is an auto bed leveling sensor for 3D printers. Uses a Hall effect sensor to detect the bed surface with high precision. Compatible with most 3D printers including Creality Ender 3, Prusa, and Anycubic.', 'Auto bed leveling sensor for 3D printers', (SELECT id FROM categories WHERE slug='3d-printer-parts'), (SELECT id FROM brands WHERE slug='creality'), '3DP-BLTOUCH-V3', 1299.00, 1999.00, ARRAY['https://images.pexels.com/photos/30658383/pexels-photo-30658383.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/33977799/pexels-photo-33977799.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'], 'https://images.pexels.com/photos/30658383/pexels-photo-30658383.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '{"Type":"Hall Effect Sensor","Operating Voltage":"5V","Probe Range":"2.5 mm","Precision":"+/- 0.005 mm","Mounting":"Standard bracket included","Compatibility":"Most 3D printers","Cable Length":"1 m","Weight":"10 g"}'::jsonb, ARRAY['High precision (+/- 0.005mm)','Auto bed leveling','Compatible with most printers','Easy installation','Includes mounting bracket'], ARRAY['1x BLTouch Sensor','1x Mounting Bracket','1x Extension Cable','1x Screws pack'], ARRAY['Creality Ender 3','Prusa MK3','Anycubic i3','SKR mainboards'], ARRAY['3d printer','bltouch','auto level','sensor','parts','upgrade'], 4.7, 89, 80, false, true, false, true, 10),
('Soldering Iron Kit 60W Adjustable Temperature', 'soldering-iron-kit-60w', 'A complete soldering iron kit with 60W adjustable temperature soldering iron, 5 soldering tips, solder wire, desoldering pump, stand, and tweezers. Perfect for electronics repair and DIY projects.', '60W adjustable temperature soldering kit with accessories', (SELECT id FROM categories WHERE slug='tools'), (SELECT id FROM brands WHERE slug='elegoo'), 'TOOL-SOL-60W', 799.00, 1299.00, ARRAY['https://images.pexels.com/photos/4709377/pexels-photo-4709377.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/4709369/pexels-photo-4709369.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/3520692/pexels-photo-3520692.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'], 'https://images.pexels.com/photos/4709377/pexels-photo-4709377.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '{"Power":"60W","Temperature Range":"200-450 C","Temperature Control":"Adjustable","Input Voltage":"220V AC","Tip Type":"900M series","Heating Element":"Ceramic","Cable Length":"150 cm","Weight":"200 g (iron only)"}'::jsonb, ARRAY['60W adjustable temperature','5 replacement tips','Ceramic heating element','Fast heat-up','Complete accessory kit'], ARRAY['1x Soldering Iron','5x Soldering Tips','1x Solder Wire','1x Desoldering Pump','1x Stand','1x Tweezers','1x Carrying Case'], ARRAY['Electronics repair','PCB soldering','DIY projects'], ARRAY['soldering','iron','tool','electronics','repair','kit'], 4.5, 92, 120, false, true, false, true, 500),
('Digital Multimeter with AC/DC Voltage and Current', 'digital-multimeter-dt830b', 'A compact digital multimeter for measuring AC/DC voltage, DC current, resistance, and transistor hFE. Features a 3.5 digit LCD display, continuity buzzer, and diode test. Perfect for electronics troubleshooting.', 'Digital multimeter for voltage, current, resistance', (SELECT id FROM categories WHERE slug='tools'), (SELECT id FROM brands WHERE slug='elegoo'), 'TOOL-MM-DT830B', 199.00, 349.00, ARRAY['https://images.pexels.com/photos/4709369/pexels-photo-4709369.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/3520692/pexels-photo-3520692.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'], 'https://images.pexels.com/photos/4709369/pexels-photo-4709369.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '{"Display":"3.5 digit LCD","DC Voltage":"200mV-600V","AC Voltage":"200-600V","DC Current":"2mA-10A","Resistance":"200 ohm-2M ohm","Battery":"9V (included)","Continuity":"Yes (buzzer)","Diode Test":"Yes","Dimensions":"126 x 70 x 25 mm","Weight":"150 g"}'::jsonb, ARRAY['Measures AC/DC voltage','DC current and resistance','Continuity buzzer','Diode test','3.5 digit LCD','Compact and portable'], ARRAY['1x Digital Multimeter','1x 9V Battery','2x Test Probes'], ARRAY['Electronics repair','DIY projects','Automotive testing'], ARRAY['multimeter','tool','measurement','electronics','diy'], 4.3, 78, 150, false, false, false, false, 150),
('YantraX Arduino Starter Kit for Beginners', 'yantrax-arduino-starter-kit', 'Complete Arduino starter kit with Arduino Uno R3 compatible board, 200+ components including sensors, motors, displays, jumper wires, breadboard, and a detailed project tutorial guide. Perfect for students and hobbyists.', 'Complete Arduino kit with 200+ components and tutorial guide', (SELECT id FROM categories WHERE slug='student-project-kits'), (SELECT id FROM brands WHERE slug='yantrax'), 'KIT-ARD-START-200', 2499.00, 3999.00, ARRAY['https://images.pexels.com/photos/33373082/pexels-photo-33373082.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/15470542/pexels-photo-15470542.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/35673122/pexels-photo-35673122.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'], 'https://images.pexels.com/photos/33373082/pexels-photo-33373082.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '{"Board":"Arduino Uno R3 Compatible","Components":"200+","Projects":"15 included","Breadboard":"830-point","Jumper Wires":"65 pieces","Sensors":"HC-SR04, DHT11, IR, PIR","Display":"16x2 LCD","Motor":"SG90 Servo","Storage":"Plastic organizer case"}'::jsonb, ARRAY['200+ electronic components','15 project tutorials','Arduino Uno R3 compatible board','830-point breadboard','Plastic organizer case','Step-by-step guide'], ARRAY['1x Arduino Uno R3 Compatible Board','1x 830-point Breadboard','65x Jumper Wires','1x HC-SR04 Ultrasonic Sensor','1x DHT11 Sensor','1x IR Sensor','1x PIR Sensor','1x 16x2 LCD Display','1x SG90 Servo Motor','1x L298N Motor Driver','1x DC Motor','1x Buzzer','1x LED Pack','1x Resistor Pack','1x Project Guide PDF','1x Storage Case'], ARRAY['Arduino IDE','STEM education','School projects','College projects'], ARRAY['arduino','starter kit','beginner','student','education','stem','kit'], 4.8, 234, 80, true, true, true, true, 1500),
('YantraX 4-DOF Robot Arm Kit', 'yantrax-robot-arm-kit', 'A 4-degree-of-freedom robot arm kit with acrylic frame, 4 SG90 servo motors, and Arduino-compatible control board. Perfect for learning robotics, inverse kinematics, and automation. Includes a joystick controller.', '4-DOF servo robot arm kit with Arduino control', (SELECT id FROM categories WHERE slug='robotics-kits'), (SELECT id FROM brands WHERE slug='yantrax'), 'KIT-ROBOT-ARM-4DOF', 2999.00, 4499.00, ARRAY['https://images.pexels.com/photos/8438967/pexels-photo-8438967.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/8439074/pexels-photo-8439074.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/8439000/pexels-photo-8439000.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'], 'https://images.pexels.com/photos/8438967/pexels-photo-8438967.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '{"Degrees of Freedom":"4","Material":"Acrylic","Servo Motors":"4x SG90","Control":"Joystick + Arduino","Power":"5V DC (USB or adapter)","Payload":"100g max","Reach":"25 cm","Assembly":"Required (approx 2 hours)"}'::jsonb, ARRAY['4 degrees of freedom','Acrylic frame','4 SG90 servo motors','Joystick controller','Arduino-compatible','Learn inverse kinematics'], ARRAY['4x SG90 Servo Motors','1x Arduino-compatible Board','1x Joystick Module','1x Acrylic Frame Set','1x USB Cable','1x Assembly Guide'], ARRAY['Arduino IDE','Custom Arduino code'], ARRAY['robotics','robot arm','kit','servo','arduino','automation','stem'], 4.6, 78, 60, true, true, true, true, 800),
('YantraX Arduino Smart Dustbin DIY Kit', 'yantrax-smart-dustbin-kit', 'A complete DIY kit to build an Arduino-based smart dustbin that opens automatically when you bring your hand near it. Includes an Arduino-compatible board, HC-SR04 ultrasonic sensor, SG90 servo motor, and all necessary components. Perfect for student projects.', 'Arduino smart dustbin project kit with all components', (SELECT id FROM categories WHERE slug='diy-kits'), (SELECT id FROM brands WHERE slug='yantrax'), 'KIT-SMART-DUSTBIN', 1499.00, 2299.00, ARRAY['https://images.pexels.com/photos/33373082/pexels-photo-33373082.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/15470542/pexels-photo-15470542.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/11579194/pexels-photo-11579194.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'], 'https://images.pexels.com/photos/33373082/pexels-photo-33373082.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '{"Board":"Arduino Uno R3 Compatible","Sensor":"HC-SR04 Ultrasonic","Motor":"SG90 Servo","Power":"USB or 9V battery","Assembly Time":"2-3 hours","Difficulty":"Beginner","Code":"Included (Arduino sketch)"}'::jsonb, ARRAY['Complete smart dustbin kit','Auto-open with hand detection','Arduino-based','Beginner friendly','Includes code and guide'], ARRAY['1x Arduino Uno Compatible Board','1x HC-SR04 Ultrasonic Sensor','1x SG90 Servo Motor','1x Servo Mounting Bracket','1x Dustbin Body (acrylic)','1x Jumper Wires','1x USB Cable','1x Project Guide'], ARRAY['Arduino IDE'], ARRAY['arduino','smart dustbin','diy kit','student project','ultrasonic','servo','beginner'], 4.8, 67, 40, true, false, true, true, 500),
('YantraX IoT Weather Station Kit with ESP8266', 'yantrax-iot-weather-station', 'Build your own IoT weather station with ESP8266 WiFi module, DHT22 temperature/humidity sensor, BMP280 pressure sensor, and OLED display. Upload data to the cloud and monitor from anywhere. Complete kit with all components.', 'ESP8266-based IoT weather station with cloud monitoring', (SELECT id FROM categories WHERE slug='diy-kits'), (SELECT id FROM brands WHERE slug='yantrax'), 'KIT-IOT-WEATHER', 1999.00, 2999.00, ARRAY['https://images.pexels.com/photos/35686438/pexels-photo-35686438.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/35673120/pexels-photo-35673120.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/35686442/pexels-photo-35686442.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'], 'https://images.pexels.com/photos/35686438/pexels-photo-35686438.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '{"Controller":"NodeMCU ESP8266","Sensors":"DHT22, BMP280","Display":"0.96 OLED I2C","Connectivity":"WiFi","Power":"USB or 5V adapter","Assembly Time":"3-4 hours","Difficulty":"Intermediate","Cloud":"ThingsBoard / custom server"}'::jsonb, ARRAY['WiFi-connected weather station','Temperature, humidity, pressure sensors','OLED display','Cloud data upload','Intermediate level'], ARRAY['1x NodeMCU ESP8266 Board','1x DHT22 Sensor','1x BMP280 Sensor','1x 0.96 OLED Display','1x Breadboard','1x Jumper Wires','1x USB Cable','1x Project Guide'], ARRAY['Arduino IDE','PlatformIO','ThingsBoard','Custom IoT platforms'], ARRAY['iot','weather station','esp8266','wifi','sensors','cloud','intermediate'], 4.7, 45, 35, true, false, true, true, 300),
('830-Point Solderless Breadboard with Power Rails', 'breadboard-830-point', 'A high-quality 830-point solderless breadboard with power rails. Perfect for prototyping circuits without soldering. Compatible with standard jumper wires and electronic components.', '830-point solderless breadboard for prototyping', (SELECT id FROM categories WHERE slug='electronics-components'), (SELECT id FROM brands WHERE slug='elegoo'), 'COMP-BB-830', 99.00, 199.00, ARRAY['https://images.pexels.com/photos/35673122/pexels-photo-35673122.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/35673127/pexels-photo-35673127.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'], 'https://images.pexels.com/photos/35673122/pexels-photo-35673122.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '{"Points":"830","Power Rails":"4","Dimensions":"165 x 55 x 9 mm","Material":"ABS Plastic","Wire Gauge":"AWG 21-26","Color":"White","Self-Adhesive":"Yes"}'::jsonb, ARRAY['830 tie-points','Power rails on both sides','Self-adhesive backing','Standard spacing','Reusable'], ARRAY['1x 830-point Breadboard'], ARRAY['Arduino','ESP32','Raspberry Pi','All through-hole components'], ARRAY['breadboard','prototyping','solderless','electronics','diy'], 4.7, 145, 800, false, false, false, false, 50),
('40-Piece M-M Jumper Wire Dupont Cable Set', 'jumper-wires-m-m-40', 'A set of 40 male-to-male jumper wires in 10cm length. 20 different colors. Perfect for breadboard prototyping and connecting components to development boards.', '40pc male-to-male Dupont jumper wires', (SELECT id FROM categories WHERE slug='electronics-components'), (SELECT id FROM brands WHERE slug='elegoo'), 'COMP-JW-MM-40', 79.00, 149.00, ARRAY['https://images.pexels.com/photos/35673127/pexels-photo-35673127.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/35673122/pexels-photo-35673122.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'], 'https://images.pexels.com/photos/35673127/pexels-photo-35673127.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '{"Type":"Male to Male","Length":"10 cm / 20 cm","Quantity":"40 pieces","Wire Gauge":"AWG 26","Colors":"10 different colors","Connector":"Dupont","Material":"Copper + PVC"}'::jsonb, ARRAY['40 pieces','10 colors','Standard Dupont spacing','Compatible with breadboards','Flexible PVC insulation'], ARRAY['1x 40-piece Jumper Wire Set'], ARRAY['Arduino','ESP32','Raspberry Pi','Breadboards'], ARRAY['jumper wires','dupont','breadboard','prototyping','cables'], 4.6, 89, 1000, false, false, false, false, 80),
('4-Channel 5V Relay Module', 'relay-module-4ch-5v', 'A 4-channel 5V relay module with optocoupler isolation. Can control high-voltage appliances up to 250V AC / 10A. Perfect for home automation, IoT, and industrial control projects.', '4-channel isolated relay module for automation', (SELECT id FROM categories WHERE slug='electronics-components'), (SELECT id FROM brands WHERE slug='hiletgo'), 'COMP-RELAY-4CH', 299.00, 499.00, ARRAY['https://images.pexels.com/photos/5276099/pexels-photo-5276099.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/35686442/pexels-photo-35686442.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'], 'https://images.pexels.com/photos/5276099/pexels-photo-5276099.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '{"Channels":"4","Trigger Voltage":"5V DC","Max Switching":"250V AC / 10A","Optocoupler":"Yes","Trigger Mode":"Active LOW","Dimensions":"75 x 55 x 20 mm","Weight":"60 g"}'::jsonb, ARRAY['4 independent relay channels','Optocoupler isolation','250V AC / 10A switching','Active LOW trigger','Status LEDs'], ARRAY['1x 4-Channel Relay Module'], ARRAY['Arduino','ESP32','Raspberry Pi','NodeMCU'], ARRAY['relay','home automation','iot','5v','4 channel'], 4.5, 67, 200, false, false, false, false, 60),
('Resistor Kit 1/4W 600-Piece 30 Values', 'resistor-kit-600pc-30val', 'A complete resistor kit with 600 pieces in 30 different values from 10 ohm to 1M ohm. 1/4W carbon film resistors with 5% tolerance. Organized in a labeled storage bag for easy selection.', '600-piece 1/4W resistor assortment kit', (SELECT id FROM categories WHERE slug='electronics-components'), (SELECT id FROM brands WHERE slug='elegoo'), 'COMP-RES-600-30', 349.00, 599.00, ARRAY['https://images.pexels.com/photos/4584612/pexels-photo-4584612.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/35673122/pexels-photo-35673122.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'], 'https://images.pexels.com/photos/4584612/pexels-photo-4584612.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '{"Type":"Carbon Film","Power Rating":"1/4W","Tolerance":"+/- 5%","Values":"30 different (10 ohm to 1M ohm)","Quantity":"600 pieces (20 each value)","Organization":"Labeled storage bag"}'::jsonb, ARRAY['600 pieces total','30 different values','1/4W power rating','5% tolerance','Organized storage'], ARRAY['1x Resistor Kit (600 pieces)','1x Storage Bag'], ARRAY['All through-hole PCB projects','Breadboard prototyping'], ARRAY['resistor','component','kit','electronics','carbon film'], 4.6, 56, 100, false, false, false, false, 200),
('7805 5V Voltage Regulator - 10 Pack', '7805-voltage-regulator-10pk', 'A pack of 10 7805 5V positive voltage regulator ICs. Provides fixed 5V output from 7-35V input. Essential component for powering 5V circuits from higher voltage sources.', '10x 7805 5V linear voltage regulator ICs', (SELECT id FROM categories WHERE slug='electronics-components'), (SELECT id FROM brands WHERE slug='sparkfun'), 'COMP-7805-10', 99.00, 199.00, ARRAY['https://images.pexels.com/photos/4584612/pexels-photo-4584612.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/3520692/pexels-photo-3520692.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'], 'https://images.pexels.com/photos/4584612/pexels-photo-4584612.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '{"Type":"Linear Voltage Regulator","Output Voltage":"5V DC","Input Voltage":"7-35V DC","Max Output Current":"1A","Dropout Voltage":"2V","Package":"TO-220","Operating Temperature":"0 to 125 C","Quantity":"10 pieces"}'::jsonb, ARRAY['Fixed 5V output','Up to 1A output current','TO-220 package','7-35V input range','10 pieces included'], ARRAY['10x 7805 Voltage Regulator ICs'], ARRAY['Arduino projects','Power supply circuits','Breadboard prototyping'], ARRAY['voltage regulator','7805','5v','component','power supply'], 4.6, 45, 500, false, false, false, false, 50),
('WS2812B Addressable LED Strip 1m 60 LEDs', 'neopixel-led-strip-1m-60', 'A 1-meter addressable RGB LED strip with 60 WS2812B LEDs. Each LED is individually addressable for stunning lighting effects. Perfect for IoT displays, ambient lighting, and creative projects.', 'Addressable RGB LED strip, 60 LEDs/meter', (SELECT id FROM categories WHERE slug='electronics-components'), (SELECT id FROM brands WHERE slug='adafruit'), 'COMP-LED-WS2812-1M', 499.00, 799.00, ARRAY['https://images.pexels.com/photos/35673128/pexels-photo-35673128.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/35673122/pexels-photo-35673122.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'], 'https://images.pexels.com/photos/35673128/pexels-photo-35673128.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '{"LED Type":"WS2812B","LEDs per meter":"60","Strip Length":"1 meter","Operating Voltage":"5V DC","Power":"18W per meter","Interface":"Single-wire digital","Colors":"16.7 million","Waterproof":"IP30","Width":"10 mm"}'::jsonb, ARRAY['60 individually addressable LEDs','16.7 million colors','Single-wire interface','5V operation','Chainable'], ARRAY['1x 1m LED Strip','1x 3-pin connector'], ARRAY['Arduino','ESP32','Raspberry Pi','NeoPixel library'], ARRAY['led','neopixel','ws2812','rgb','addressable','lighting'], 4.7, 89, 150, false, true, true, false, 50),
('LoRa SX1278 433MHz Long Range Module', 'lora-sx1278-433mhz', 'The SX1278 LoRa module provides long-range, low-power wireless communication up to 15km. Operating at 433MHz with SPI interface. Perfect for IoT, remote sensing, and long-range telemetry applications.', 'Long-range LoRa wireless module 433MHz', (SELECT id FROM categories WHERE slug='communication-modules'), (SELECT id FROM brands WHERE slug='seeed-studio'), 'COMM-LORA-433', 399.00, 599.00, ARRAY['https://images.pexels.com/photos/35686436/pexels-photo-35686436.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/35686430/pexels-photo-35686430.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'], 'https://images.pexels.com/photos/35686436/pexels-photo-35686436.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '{"Frequency":"433 MHz","Modulation":"LoRa / FSK","Range":"Up to 15 km","Max Data Rate":"300 kbps","Interface":"SPI","Operating Voltage":"3.3V","Output Power":"+20 dBm","Sensitivity":"-148 dBm","Dimensions":"24 x 24 x 3 mm","Weight":"3 g"}'::jsonb, ARRAY['Up to 15km range','Low power consumption','SPI interface','433MHz frequency','LoRa modulation'], ARRAY['1x SX1278 LoRa Module','1x Antenna','1x Header pins'], ARRAY['Arduino','ESP32','Raspberry Pi','STM32'], ARRAY['lora','wireless','433mhz','iot','long range','telemetry'], 4.5, 34, 100, false, false, true, false, 3),
('5V 3A USB Power Supply Adapter', 'usb-power-supply-5v-3a', 'A reliable 5V 3A USB power supply adapter for powering development boards, Raspberry Pi, and other electronics projects. Features over-current and short-circuit protection.', '5V 3A USB power adapter for dev boards', (SELECT id FROM categories WHERE slug='accessories'), (SELECT id FROM brands WHERE slug='sparkfun'), 'ACC-USB-5V3A', 349.00, 499.00, ARRAY['https://images.pexels.com/photos/35673127/pexels-photo-35673127.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/35673122/pexels-photo-35673122.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'], 'https://images.pexels.com/photos/35673127/pexels-photo-35673127.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '{"Output Voltage":"5V DC","Output Current":"3A (max)","Input Voltage":"100-240V AC","Connector":"USB-A","Cable Length":"1.5 m","Protection":"Over-current, Short-circuit","Certification":"CE, FCC","Weight":"100 g"}'::jsonb, ARRAY['5V 3A output','Over-current protection','Short-circuit protection','1.5m cable','CE/FCC certified'], ARRAY['1x 5V 3A USB Power Adapter'], ARRAY['Raspberry Pi 4','Arduino','ESP32','Most USB-powered devices'], ARRAY['power supply','adapter','usb','5v','accessories'], 4.4, 45, 200, false, false, false, false, 100)
